source.jsLib:
var _DP_JV = null, _DP_BK = null, _DP_CH = null;
var _DP_ILLU_DIAG = '';   
function _dpSetCtx(jv, bk, ch) {
    try { if (jv) _DP_JV = jv; } catch (e1) {}
    try { if (bk) _DP_BK = bk; } catch (e2) {}
    try { if (ch) _DP_CH = ch; } catch (e3) {}
    return _DP_JV;
}
function _dpScopeChapter() {
    try { if (typeof chapter !== 'undefined' && chapter) return chapter; } catch (e1) {}
    try { if (_DP_CH) return _DP_CH; } catch (e2) {}
    return null;
}
function _dpJv(jv) {
    if (jv) return jv;
    if (_DP_JV) return _DP_JV;
    try { if (typeof java !== 'undefined' && java) return java; } catch (e1) {}
    try { if (typeof source !== 'undefined' && source) return source; } catch (e2) {}
    return null;
}

var _DP_UA = 'Mozilla/5.0 (Linux; Android 12; Redmi K40 Build/SKQ1.220213.001; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/110.0.0.0 Mobile Safari/537.36';
var _DP_LANG = 'zh-CN,zh;q=0.9';
var _DP_QD_DIAG = '';
var _DP_DEBUG = true;          
var _DP_DEBUG_OK = false;      
var _DP_NET_ERR = '';          
var _DP_CSRF = '';             
var _DP_LAST_FAIL = '';        
var _DP_HOT_EMPTY = false;
var _DP_HOT_DIAG = '';
var _DP_IMG_VH = 55;

var _DP_SERVER = 'http://43.139.147.103:8070';   

function _dpSrv() {
    try {
        var sc = _dpSrcOf(_dpJv());
        if (sc && typeof sc.get === 'function') {
            var v = String(sc.get('agg_server') || '').replace(/\/+$/, '');
            if (v) return v;
        }
    } catch (e0) {}
    return _DP_SERVER;
}
var _dpBidCache = {};          
var _dpCatCache = {};          

function _dpFlat(s) {
    try { s = String(s == null ? '' : s); } catch (e0) { s = ''; }
    try { s = s.split('').join(''); } catch (e1) {}
    return s;
}
function _dpFlatHd(hd) {
    var out = {};
    try { for (var k in hd) { out[_dpFlat(k)] = _dpFlat(hd[k]); } } catch (e) { return hd; }
    return out;
}

function _dpToast(jav, msg) {
    if (!_DP_DEBUG) return;
    try { jav.toast(msg); } catch (e) {}
}

function _dpT2S(jav, s) {
    var v = String(s == null ? '' : s);
    if (!v) return v;
    try { var r = jav.t2s(v); if (r) return String(r); } catch (e) {}
    return v;
}
function _dpGetJson(jav, url, headers) {
    try {
        var r = jav.get(url, headers);
        var body = String(r.body() || '');
        if (!body) return null;
        return JSON.parse(body);
    } catch (e) { _DP_NET_ERR = String(e); return null; }
}
function _dpIsHtmlBlock(t) {
    return /<(p|br|div|h[1-6])[\s>\/]/i.test(String(t == null ? '' : t));
}

function _dpPlainText(s) {
    return String(s == null ? '' : s)
        .replace(/<script[\s\S]*?<\/script>/gi, '')
        .replace(/<style[\s\S]*?<\/style>/gi, '')
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<\/p>/gi, '\n')
        .replace(/<\/div>/gi, '\n')
        .replace(/<[^>]*>/g, '')
        .replace(/&nbsp;/gi, ' ')
        .replace(/&ldquo;/gi, '“').replace(/&rdquo;/gi, '”')
        .replace(/&hellip;/gi, '…').replace(/&mdash;/gi, '—')
        .replace(/&amp;/gi, '&').replace(/&lt;/gi, '<')
        .replace(/&gt;/gi, '>').replace(/&quot;/gi, '"')
        .replace(/&#\d+;/g, ' ');
}
function _dpInjectServer(t, nm, au, cn, jav) {
    try {
        var plain = _dpIsHtmlBlock(t) ? _dpPlainText(t) : t;
        var body = 'name=' + encodeURIComponent(nm)
                 + '&author=' + encodeURIComponent(au)
                 + '&chapter=' + encodeURIComponent(cn)
                 + '&text=' + encodeURIComponent(plain)
                 + '&hot=' + ((_dpSegCardOn(jav) || _dpEndCardOn(jav)) ? '1' : '0')
                 + '&bubble=' + (_dpBubbleOn(jav) ? '1' : '0')
                 + '&segcard=' + (_dpSegCardOn(jav) ? '1' : '0')
