    return '来源未知';
}

function _aqCodeStockText(st) {
    try {
        var a = st || _aqGet('/user/auth/status');
        if (a) {
            var tot = a.pool_total;
            var left = a.remaining_pool;
            if (a.pool_exhausted === true) {
                return '🎟 注册码余额：0 个名额（已发完，等释放）';
            }
            if (left != null && tot != null) {
                var t = '🎟 注册码余额：剩 ' + left + ' / ' + tot + ' 个名额可注册';
                if (a.low_stock === true) { t += ' · 库存偏低'; }
                if (a.remaining_today != null) { t += '｜今日还可发 ' + a.remaining_today; }
                return t;
            }
        }
    } catch (eS) {}
    return '🎟 注册码余额：读取失败 · 点这里重试';
}

function _aqQuotaText(st) {
    try {
        var a = st || _aqGet('/user/auth/status');
        if (a && a.code === 0 && a.loggedIn && a.quota) {
            var q = a.quota;
            var lim = (q.limit == null) ? '不限' : q.limit;
            var t = '📊 今日已读 ' + q.used + ' / ' + lim + ' 章';
            if (q.remaining != null) { t += '（剩 ' + q.remaining + '）'; }
            if (q.bypass) { t += ' · 暂不计限'; }
            t += '｜' + _aqLimitSrcText(q);
            return t;
        }
        if (a && a.loggedIn === false) {
            return '📊 未登录 · 登录后这里显示今日额度';
        }
    } catch (e) {}
    return '📊 额度获取失败 · 点这里重试';
}

function _aqWhoText(st) {
    try {
        var a = st || _aqGet('/user/auth/status');
        if (!a) return '🔌 状态未知 · 点这里重试';
        if (a.code === 0 && a.loggedIn) {
            var em = '';
            try { em = String((a.user && a.user.email) || ''); } catch (eE) {}
            var q = a.quota || {};
            var lim = (q.limit == null) ? '不限' : (q.limit + ' 章');
            return '✅ 已登录' + (em ? '：' + em : '') + '｜今日 ' + q.used + ' / ' + lim
                 + '（' + _aqLimitSrcText(q) + '）';
        }
        if (a.code === 401 || a.loggedIn === false) {
            return '❌ 未登录 · 会话已失效，填邮箱密码再点登录';
        }
    } catch (e) {}
    return '⚠ 登录状态读取失败 · 点这里重试';
}

function aqStock() {
    try {
        var a = _aqGet('/user/auth/status');
        if (!a) { _aqToast('网络错误，请重试'); return ''; }
        var t = _aqCodeStockText(a);
        try { java.upLoginData({ 'aq_stock': t }); } catch (e1) {}
        var more = '';
        if (a.remaining_pool != null && a.pool_total != null) {
            more = '\n已发 ' + (a.pool_total - a.remaining_pool) + ' / ' + a.pool_total + ' 个名额';
        }
        _aqToast(t + more);
    } catch (e) { _aqToast('查询出错'); }
    return '';
}

function aqCheck() {
    try {
        var a = _aqGet('/user/auth/status');
        if (!a) { _aqToast('网络错误，请重试'); return ''; }
        var t = _aqWhoText(a);
        _aqToast(t);
        try { java.upLoginData({ 'aq_who': t }); } catch (e1) {}
        try { java.upLoginData({ 'aq_quota_line': _aqQuotaText(a) }); } catch (e2) {}
        if (a.code === 0 && a.loggedIn) {
            try {
                var em = String((a.user && a.user.email) || '');
                if (em) {
                    java.upLoginData({ '邮箱': em });
                    source.put('aq_email', em);   
                }
            } catch (e3) {}
        }
    } catch (e) {
        _aqToast('检测出错：' + (e && e.message ? e.message : e));
    }
    return '';
}

function aqQuota() {
    try {
        var j = _aqGet('/user/api/quota');
        if (!j) { _aqToast('网络错误，请重试'); return ''; }
        if (j.code !== 0) {
            _aqToast(j.message || '未登录');
            try { java.upLoginData({ 'aq_quota_line': '📊 未登录 · 登录后这里显示今日额度' }); } catch (e0) {}
            return '';
        }
        var lim = (j.limit == null) ? '不限' : j.limit;
        var t = '📊 今日已读 ' + j.used + ' / ' + lim + ' 章';
        if (j.remaining != null) { t += '（剩 ' + j.remaining + '）'; }
        if (j.bypass) { t += ' · 暂不计限'; }
        try { java.upLoginData({ 'aq_quota_line': t }); } catch (e1) {}
        _aqToast(t + '\n重读同一章不重复计 · 每日本地 0 点重置');
    } catch (e) {
        _aqToast('查询出错');
    }
    return '';
}

function aqKickOthers() {
    try {
        var d = _aqGet('/user/api/devices');
        if (!d || d.code !== 0) { _aqToast('请先登录'); return ''; }
        var list = d.devices || [];
        var n = 0, names = [];
        for (var i = 0; i < list.length; i++) {
            var it = list[i];
            if (it.current || !it.active) { continue; }
            if (!it.device) { continue; }   
            names.push((it.device_label || '?') + '(' + it.active + ')');
            var j = _aqPost('/user/api/devices/kick', { device: it.device });
            if (j && j.code === 0) { n += (j.kicked || 0); }
        }
        if (!n) { _aqToast('没有其它在线设备（共 ' + list.length + ' 台）'); return ''; }
        _aqToast('已下线 ' + n + ' 个会话：' + names.join('、'));
    } catch (e) {
        _aqToast('操作出错：' + (e && e.message ? e.message : e));
    }
    return '';
}

function aqLogout() {
    try {
        _aqPost('/user/auth/logout', {});
        try { cookie.removeCookie(_aqBase()); } catch (e1) {}
        try { java.upLoginData({ 'aq_quota_line': _aqQuotaText() }); } catch (e2) {}
        _aqToast('已退出登录');
        try { java.refreshContent(); } catch (e3) {}
    } catch (e) {}
    return '';
}

function _dpLuRow(name, label, action, dynLabel, basis) {
    var r = {
        name: name, type: 'button',
        style: {
            layout_flexGrow: 1,
            layout_flexBasisPercent: (basis == null ? 0.45 : basis)
        }
    };
    r.viewName = dynLabel ? String(label) : JSON.stringify(String(label));
    if (action) r.action = action;
    return r;
}

function _dpLuFallback() {
    try {
        return JSON.stringify([
            _dpLuRow('lu_hint', '↓   账号登录   ↓', null, false, 1),
            _dpLuRow('lu_login', '🔑 登录', 'login(true)', false, 0.45),
            _dpLuRow('lu_reg', '📝 注册', 'register()', false, 0.45),
            _dpLuRow('lu_tip', '每日 100 章 · 重读不重复计 · 未登录无法阅读', null, false, 1)
        ]);
    } catch (e) { return '[]'; }
}

function _dpAqRows() {
    var r = [];
    var hint = '点「🎫 领取注册码」自助领码：一机一码，换机先解绑';
    var st = _aqGet('/user/code/state');
    if (st && st.code === 0) {
        if (st.codeHint) {
            var parts = String(st.codeHint).split('\n');
            hint = parts[0];
        }
        if (st.selfCodeEnabled === false) {
            r.push(_dpLuRow('aq_off', '⛔ 管理员已暂停发码', null, false, 1));
        }
    }
    var _st = null;
    try { _st = _aqGet('/user/auth/status'); } catch (eSt) {}
    var qtext = '📊 今日额度加载中…';
    try { qtext = _aqQuotaText(_st); } catch (eq) {}
    r.push(_dpLuRow('aq_quota_line', qtext, 'aqQuota()', false, 1));
    var whoText = '🔌 登录状态检测中…';
    try { whoText = _aqWhoText(_st); } catch (ew) {}
    r.push(_dpLuRow('aq_who', whoText, 'aqCheck()', false, 1));
    r.push(_dpLuRow('aq_head', '↓  注册码登录（阅读额度）  ↓', null, false, 1));
    var stockText = '🎟 注册码余额加载中…';
    try { stockText = _aqCodeStockText(_st); } catch (eSk) {}
    r.push(_dpLuRow('aq_stock', stockText, 'aqStock()', false, 1));
    r.push({ name: '注册码', type: 'text', default: '' });
    var _mail = '';
    try { _mail = String(source.get('aq_email') || ''); } catch (eM) {}
    r.push({ name: '邮箱', type: 'text', default: _mail });
    r.push({ name: '密码', type: 'password', default: '' });
    r.push(_dpLuRow('aq_check', '🔄 检测登录状态', 'aqCheck()', false, 1));
    r.push(_dpLuRow('aq_login', '🔑 登录', 'login(true)', false, 0.45));
    r.push(_dpLuRow('aq_reg', '📝 注册', 'register()', false, 0.45));
    r.push(_dpLuRow('aq_issue', '🎫 领取注册码', 'aqIssue()', false, 0.45));
    r.push(_dpLuRow('aq_release', '♻️ 解绑当前设备', 'aqRelease()', false, 0.45));
    r.push(_dpLuRow('aq_find', '🔍 找回注册码', 'aqFind()', false, 0.45));
    r.push(_dpLuRow('aq_kick', '🚪 下线其它设备', 'aqKickOthers()', false, 0.45));
    r.push(_dpLuRow('aq_logout', '⏏️ 退出登录', 'aqLogout()', false, 1));
    r.push(_dpLuRow('aq_ver', '📦 版本检查中…', 'aqVer()', false, 1));
    r.push(_dpLuRow('aq_upd', '⟳ 检查书源更新', '_dpSrcUpd()', false, 1));
    var tip = hint;
    if (st && st.code === 0) {
        if (st.pool_exhausted === true) {
            tip += '｜注册码已发完，等待释放';
        } else if (st.remaining_today != null) {
            tip += '｜今日还可发 ' + st.remaining_today + ' 个';
        }
        tip += '｜每日 ' + (st.dailyLimit == null ? 100 : st.dailyLimit) + ' 章';
    }
    r.push(_dpLuRow('aq_tip', tip, null, false, 1));
    return r;
}

function _dpAqUi(bko, jav) {
    try {
        var rows = _dpAqRows();
        try {
            if (typeof _dpLuList === 'function') {
                var rest = JSON.parse(_dpLuList(bko, jav));
                if (rest && rest.length) rows = rows.concat(rest);
            }
        } catch (eB) {}
        return JSON.stringify(rows);
    } catch (e) { return '[]'; }
}

