    ][c || 0],
    [
        "",
        "-hl",
        "-lf",
        "-lq",
        "-sinfonlinea",
        "-sinfonlineb",
        "-sinfonlinec",
    ][d || 0],
    [".", ""][a == 4 ? 1 : 0],
    [
        "snssdk",
